mod tests {
    use super::*;

    struct StubLine {
        name: &'static str,
        claims: &'static str,
        augment: Option<fn(clap::Command) -> clap::Command>,
        consumed: &'static [&'static str],
        requirements: &'static [ArgRequirement],
    }

    impl StubLine {
        const fn new(
            name: &'static str,
            claims: &'static str,
            augment: Option<fn(clap::Command) -> clap::Command>,
