    #[test]
    fn provided_args_reports_only_explicitly_set_flags() {
        let registry = registry();
        let cmd = registry.build_command(clap::Command::new("test"));
        let matches = cmd
            .clone()
            .try_get_matches_from(["test", "--tp-size", "2", "--line-a-flag"])
